class Solution:
    def maxScoreIndices(self, nums: List[int]) -> List[int]:
        n = len(nums)
        best, ans = -1, []
        for i in range(n + 1):
            score = sum(x == 0 for x in nums[:i]) + sum(x == 1 for x in nums[i:])
            if score > best:
                best, ans = score, [i]
            elif score == best:
                ans.append(i)
        return ans

