class Solution {
public:
    vector<int> maxScoreIndices(vector<int>& nums) {
        int n = nums.size(), best = -1;
        vector<int> ans;
        for (int i = 0; i <= n; ++i) {
            int score = 0;
            for (int j = 0; j < i; ++j) score += nums[j] == 0;
            for (int j = i; j < n; ++j) score += nums[j] == 1;
            if (score > best) { best = score; ans.assign(1, i); }
            else if (score == best) ans.push_back(i);
        }
        return ans;
    }
};

