class Solution:
    def maxScoreIndices(self, nums: List[int]) -> List[int]:
        n = len(nums)
        zeros = [0] * (n + 1)
        ones = [0] * (n + 1)
        for i in range(n):
            zeros[i + 1] = zeros[i] + (nums[i] == 0)
            ones[n - 1 - i] = ones[n - i] + (nums[n - 1 - i] == 1)
        best = max(zeros[i] + ones[i] for i in range(n + 1))
        return [i for i in range(n + 1) if zeros[i] + ones[i] == best]

