class Solution:
    def maxScoreIndices(self, nums: List[int]) -> List[int]:
        score = nums.count(1)
        best = score
        ans = [0]
        for i, x in enumerate(nums):
            score += 1 if x == 0 else -1
            if score > best:
                best = score
                ans = [i + 1]
            elif score == best:
                ans.append(i + 1)
        return ans

